margin:0;padding:15px 8px;color:#65716c;font-size:15px;line-height:1.4}.fp-explain{display:flex;align-items:center;gap:9px;margin:4px 2px;color:#52615c;font-size:15px}.fp-explain svg{color:#2e7d7a}.fp-undo{min-height:44px;margin-left:8px;padding:5px 9px;border:1px solid #9fb8ae;border-radius:7px;background:#263b35;color:white;font:600 15px var(--font-verly-body);cursor:pointer}.fp-dialog{padding:0;width:min(680px,calc(100vw - 32px));max-height:90dvh;border:0;border-radius:20px;box-shadow:0 25px 80px #111a1f45}.fp-dialog::backdrop{background:#121b19a8}.fp-dialog-head{display:flex;justify-content:space-between;gap:14px;padding:23px 25px 17px;border-bottom:1px solid #e0e7e4}.fp-dialog-head h2{margin:3px 0;font:600 26px var(--font-verly-display)}.fp-dialog-head p:last-child{margin:0;color:#586560;font-size:15px}.fp-close{display:grid;place-items:center;flex:0 0 44px;width:44px;height:44px;border:0;border-radius:50%;background:#eff3f1;color:#141a1f;cursor:pointer}.fp-dialog-body{display:grid;gap:17px;padding:20px 25px;overflow:auto}.fp-highlight{display:grid;grid-template-columns:1fr auto;gap:7px 10px;padding:15px;border-radius:12px;background:#eff7f5}.fp-highlight span{color:#596761;font-size:15px}.fp-highlight strong{grid-column:2;grid-row:1/3;align-self:center;font:600 22px var(--font-verly-mono)}.fp-highlight b{font-size:16px}.fp-detail{margin:0;font-size:16px;line-height:1.5}.fp-drawing{max-width:270px;margin:auto}.fp-measure-callout{display:flex;align-items:center;gap:10px;padding:13px;border-radius:10px;background:#fbe8cf;color:#804308;font-size:15px}.fp-step{display:flex;align-items:center;gap:11px;padding:13px;border:1px solid #dce4e1;border-radius:10px}.fp-step svg{color:#2e7d7a}.fp-step div{display:grid;gap:3px}.fp-step small{font-size:15px;color:#5d6964}.fp-step strong{font-size:16px}.fp-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:14px 25px 21px;border-top:1px solid #e0e7e4}.fp-mobile-tabs{display:none}
@media(max-width:1200px){.fp-board{grid-template-columns:repeat(6,minmax(245px,1fr))}.fp-column{min-width:245px}}
@media(max-width:720px){.fp-head{align-items:flex-start;flex-direction:column}.fp-mobile-tabs{display:flex;gap:8px;overflow:auto;padding:0 0 12px}.fp-mobile-tabs button{flex:0 0 auto;min-height:44px;padding:8px 12px;border:1px solid #cbd6d2;border-radius:999px;background:#fff;color:#26352f;font:500 15px var(--font-verly-body)}.fp-mobile-tabs button span{margin-left:5px;color:#60706a}.fp-mobile-tabs button.active{border-color:#2e7d7a;background:#2e7d7a;color:#fff}.fp-mobile-tabs button.active span{color:#e0f0ec}.fp-board{display:block;overflow:visible;padding:0}.fp-column{display:none;min-width:0}.fp-column-mobile-active{display:block}.fp-col-chevron{display:block}.fp-cards{grid-template-columns:1fr}.fp-explain{align-items:flex-start}.fp-actions{flex-wrap:wrap;padding-left:18px;padding-right:18px}.fp-actions>*{flex:1}.fp-dialog-head,.fp-dialog-body{padding-left:18px;padding-right:18px}}
@media(min-width:721px){.fp-mobile-tabs{display:flex;gap:8px;overflow:auto;margin-bottom:12px;padding-bottom:5px}.fp-mobile-tabs button{min-height:44px;flex-shrink:0;padding:8px 13px;border:1px solid #C9D5D1;border-radius:999px;background:white;color:#354542;font:15px var(--font-verly-body);cursor:pointer}.fp-mobile-tabs button.active{background:#2E7D7A;color:white;border-color:#2E7D7A}.fp-mobile-tabs button span{margin-left:6px}}
@media(max-width:767px){.preview-notice{position:fixed;bottom:calc(90px + env(safe-area-inset-bottom));left:16px;right:16px;z-index:45;flex-wrap:wrap}}
</style>
